b}}]"},{"expectedAnswer":"]-\\infty;+\\infty["}],"statement":"On considère les intervalles $I=]-\\infty;{{b}}]$ et $J=]{{a}};+\\infty[$. Écris chaque résultat sous la forme d'un intervalle ou d'une réunion d'intervalles ; l'ensemble vide s'écrit $\\varnothing$.\n\n$I\\cap J=?$\n\n$I\\cup J=?$","variables":[{"name":"a","expression":"-9..5"},{"name":"g1","expression":"1..5"},{"name":"b","expression":"{{eval:a+g1}}"}],"correction":{"steps":["$I\\cap J$ : les réels tels que $x\\leqslant {{b}}$ **et** $x>{{a}}$ ; comme ${{a}}<{{b}}$, $I\\cap J=\\textcolor{{{color:primary.0}}}{]{{a}};{{b}}]}$.","$I\\cup J$ : tout réel $x$ vérifie $x\\leqslant {{b}}$ ou $x>{{a}}$ (si $x>{{b}}$, alors $x>{{a}}$). Donc $I\\cup J=\\textcolor{{{color:primary.0}}}{]-\\infty;+\\infty[}=\\mathbb{R}$."]}}],"shared":{"blankDefaults":{"answerKind":"intervalles"}},"test_specs":[{"answers":["]1;4]","[-2;6["],"expected":{"status":"correct"},"variables":{"a":"-2","g1":"3","g2":"3","g3":"2"},"description":"v0 [−2;4] et ]1;6[ : justes","variationIndex":0},{"answers":["[-2;6[","]1;4]"],"expected":{"status":"incorrect"},"variables":{"a":"-2","g1":"3","g2":"3","g3":"2"},"description":"v0 : ∩ et ∪ échangés","variationIndex":0},{"answers":["[1;4]","[-2;6["],"expected":{"status":"incorrect"},"variables":{"a":"-2","g1":"3","g2":"3","g3":"2"},"description":"v0 : crochet de 1 mal orienté","variationIndex":0},{"answers":["]1;4]","[-2;6]"],"expected":{"status":"incorrect"},"variables":{"a":"-2","g1":"3","g2":"3","g3":"2"},"description":"v0 : réunion fermée en 6","variationIndex":0},{"answers":["\\varnothing","[-2;1[\\cup[3;6]"],"expected":{"status":"correct"},"variables":{"a":"-2","t":"1","g1":"3","g2":"2","g3":"3"},"description":"v1 disjoints : justes","variationIndex":1},{"answers":["\\varnothing","[3;6]\\cup[-2;1["],"expected":{"status":"correct"},"variables":{"a":"-2","t":"1","g1":"3","g2":"2","g3":"3"},"description":"v1 disjoints : réunion dans l'autre ordre","variationIndex":1},{"answers":["\\{\\}","[-2;1[\\cu