insert into _q2c_modeles values ('8c31675a-44af-48df-bb3e-cde85a8d3f35', $q2c$Ensembles$q2c$, $q2c$Ensembles de nombres$q2c$, $q2c$intervalles$q2c$, array['1_SPE'], 'draft',
  $q2c${"title":"Réunion, intersection et complémentaire d'intervalles","description":"Écrire I ∩ J, I ∪ J ou un complémentaire dans ℝ : chevauchement, intervalles disjoints ou accolés, demi-droites","variations":[{"blanks":[{"expectedAnswer":"]{{c}};{{b}}]"},{"expectedAnswer":"[{{a}};{{d}}["}],"statement":"On considère les intervalles $I=[{{a}};{{b}}]$ et $J=]{{c}};{{d}}[$. Écris chaque résultat sous la forme d'un intervalle ou d'une réunion d'intervalles ; l'ensemble vide s'écrit $\\varnothing$.\n\n$I\\cap J=?$\n\n$I\\cup J=?$","variables":[{"name":"a","expression":"-9..2"},{"name":"g1","expression":"1..4"},{"name":"c","expression":"{{eval:a+g1}}"},{"name":"g2","expression":"1..4"},{"name":"b","expression":"{{eval:c+g2}}"},{"name":"g3","expression":"1..4"},{"name":"d","expression":"{{eval:b+g3}}"}],"correction":{"steps":["On place les deux intervalles sur une droite graduée : ${{a}}<{{c}}<{{b}}<{{d}}$, ils se chevauchent entre ${{c}}$ et ${{b}}$.","$I\\cap J$ : les réels qui sont dans $I$ **et** dans $J$, c'est-à-dire tels que $x>{{c}}$ et $x\\leqslant {{b}}$ : $I\\cap J=\\textcolor{{{color:primary.0}}}{]{{c}};{{b}}]}$.","$I\\cup J$ : les réels qui sont dans $I$ **ou** dans $J$ ; il n'y a pas de « trou » entre les deux : $I\\cup J=\\textcolor{{{color:primary.0}}}{[{{a}};{{d}}[}$ (${{a}}$ est dans $I$, ${{d}}$ n'est ni dans $I$ ni dans $J$)."]}},{"blanks":[{"expectedAnswer":"\\varnothing"},{"expectedAnswer":"[{{a}};{{b}}[\\cup[{{c}};{{d}}]"}],"statement":"On considère les intervalles $I=[{{a}};{{b}}[$ et $J=[{{c}};{{d}}]$. Écris chaque résultat sous la forme d'un intervalle ou d'une réunion d'intervalles ; l'ensemble vide s'écrit $\\varnothing$.\n\n$I\\cap J=?$\n\n$I\\cup J=?$","variables":[{"name":"a","expression":"-9..2"},{"name":"g1","expression":"1..4"},{"name":"b","expression":"{{eval:a+g1}}"},{"name":"t","expression":"0..1"},{"name":"g2","expression":"1..3"},{"name":"c","expression":"{{eval:b+t*g2}}"},{"name":"g3","expression":"1..4"},{"name":"d","expression":"{{eval:c+g3}}"}],"correction":{"steps":["{{if:t=1|${{b}}<{{c}}$ : les deux intervalles n'ont aucun point commun, donc $I\\cap J=\\textcolor{{{color:primary.0}}}{\\varnothing}$.}}{{if:t=0|${{b}}$ n'appartient pas à $I$ (crochet ouvert) : les deux intervalles n'ont aucun point commun, donc $I\\cap J=\\textcolor{{{color:primary.0}}}{\\varnothing}$.}}","{{if:t=1|Entre ${{b}}$ et ${{c}}$, il y a un « trou » : la réunion ne s'écrit pas avec un seul intervalle, $I\\cup J=\\textcolor{{{color:primary.0}}}{[{{a}};{{b}}[\\cup[{{c}};{{d}}]}$.}}{{if:t=0|$J$ commence exactement là où $I$ s'arrête, et ${{b}}\\in J$ : il n'y a pas de trou, $I\\cup J=\\textcolor{{{color:primary.0}}}{[{{a}};{{d}}]}$.}}"]}},{"blanks":[{"expectedAnswer":"]-\\infty;{{a}}[\\cup[{{b}};+\\infty["},{"expectedAnswer":"]{{c}};+\\infty["}],"statement":"Dans $\\mathbb{R}$, on considère les intervalles $I=[{{a}};{{b}}[$ et $J=]-\\infty;{{c}}]$. Écris chaque résultat sous la forme d'un intervalle ou d'une réunion d'intervalles ; l'ensemble vide s'écrit $\\varnothing$.\n\nComplémentaire de $I$ dans $\\mathbb{R}$ : $\\overline{I}=?$\n\nComplémentaire de $J$ dans $\\mathbb{R}$ : $\\overline{J}=?$","variables":[{"name":"a","expression":"-9..4"},{"name":"g1","expression":"1..6"},{"name":"b","expression":"{{eval:a+g1}}"},{"name":"c","expression":"-9..9"}],"correction":{"steps":["$\\overline{I}$ contient les réels qui ne sont **pas** dans $I$ : ceux qui sont strictement inférieurs à ${{a}}$ (${{a}}$ est dans $I$) et ceux qui sont supérieurs ou égaux à ${{b}}$ (${{b}}$ n'est pas dans $I$) : $\\overline{I}=\\textcolor{{{color:primary.0}}}{]-\\infty;{{a}}[\\cup[{{b}};+\\infty[}$.","$J$ contient les réels $x\\leqslant {{c}}$ ; son complémentaire contient ceux tels que $x>{{c}}$ : $\\overline{J}=\\textcolor{{{color:primary.0}}}{]{{c}};+\\infty[}$. Les crochets s'inversent : une borne incluse dans $J$ est exclue de $\\overline{J}$."]}},{"blanks":[{"expectedAnswer":"]{{a}};{{b}}]"},{"expectedAnswer":"]-\\infty;+\\infty["}],"