  $q2c${"title":"Résoudre une équation avec une valeur absolue","description":"Par la distance : les nombres à distance b de a","variations":[{"blanks":[{"expectedAnswer":"{{eval:a+b}}"},{"expectedAnswer":"{{eval:a-b}}"}],"statement":"Résous cette équation.\n\n$$abs(x{{eval:-(a);+}})={{b}}$$\n\n$x=?$ ou $x=?$","variables":[{"name":"a","expression":"1..9;±"},{"name":"b","expression":"1..9"}],"conditions":["abs(a) != abs(b)"],"correction":{"steps":["$\\left\\lvert x{{eval:-(a);+}}\\right\\rvert$ est la distance entre $x$ et ${{a}}$ : on cherche les nombres situés à la distance ${{b}}$ de ${{a}}$.","Il y en a deux, un de chaque côté de ${{a}}$ : ${{a}}-{{b}}={{eval:a-b}}$ et ${{a}}+{{b}}={{eval:a+b}}$.","Donc $x=\\textcolor{{{color:primary.0}}}{ {{eval:a+b}} }$ ou $x=\\textcolor{{{color:primary.0}}}{ {{eval:a-b}} }$."]}}],"shared":null,"test_specs":[{"answers":["13","-5"],"expected":{"status":"correct","constraintViolations":[]},"variables":{"a":"4","b":"9"},"description":"|x-4|=9 : 13 ou -5","variationIndex":0},{"answers":["-5","13"],"expected":{"status":"correct","constraintViolations":[]},"variables":{"a":"4","b":"9"},"description":"ordre libre","variationIndex":0},{"answers":["-13","5"],"expected":{"status":"incorrect","constraintViolations":[]},"variables":{"a":"4","b":"9"},"description":"signe de a inversé : -13 ou 5","variationIndex":0},{"answers":["-5","-7"],"expected":{"status":"correct","constraintViolations":[]},"variables":{"a":"-6","b":"1"},"description":"|x+6|=1 : -5 ou -7","variationIndex":0}]}$q2c$::jsonb,
